mapper.select:
		select t5.tmpl_id as tmplId,t1.scene_name as tmplName		
		  from stt_scene t1, stt_scene_tips t2, stt_scene_tips t3,
		  	   stt_stress_scene t4, stt_stress_tmpl t5

			t1.is_tmpl = #{isTmpl, jdbcType=VARCHAR}
		   	and t1.scene_id = t2.scene_id

		   		and t2.dict_code = #{riskType, jdbcType=VARCHAR}


		   		and t2.tips_value = #{riskTypeCode, jdbcType=VARCHAR}

		   	and t1.scene_id = t3.scene_id

		   		and t3.dict_code = #{sceneType, jdbcType=VARCHAR}


		   		and t3.tips_value = #{sceneTypeCode, jdbcType=VARCHAR}

		   	and t4.scene_id = t1.scene_id 
            and t5.tmpl_id = t4.busi_id

select t4.ind_Id indId, t4.ind_name indName, t4.remark from stt_stress_scene t1, stt_stress_tmpl t2, stt_stress_indicator t3, stt_indicator t4
t1.busi_id = t2.tmpl_id and t2.tmpl_id = t3.model_id and t3.ind_id = t4.ind_id and t3.stt_busi_type = '03'
and t1.busi_id=#{modelId, jdbcType=VARCHAR}
and t4.ind_ype=#{indType, jdbcType=VARCHAR}

SELECT SCENE_ID sceneId, SCENE_NAME sceneName FROM STT_SCENE WHERE 1=1
AND SCENE_NAME = #{sceneName, jdbcType=VARCHAR}
AND SCENE_ID != #{sceneId, jdbcType=VARCHAR}

mapper.delete:
    	begin

			delete from stt_scene_ftrtips a where a.scene_id = #{sceneId};

			delete from stt_scene_curve b where b.scene_id = #{sceneId};

			delete from stt_scene_factor g where g.scene_id = #{sceneId};
		end;
